test('adhésions : commandes et toutes les autres fonctions intactes, lecture et filtres identiques',()=>{const before=parse(at(base,'plateau-organisations-quetes.js')),after=parse(code('plateau-organisations-quetes.js'));for(const name of ['ouvrirDemandesAdhesion','ouvrirInviterMembreOrga']){const fn=t=>t.body.find(n=>n.type==='FunctionDeclaration'&&n.id.name===name),a=fn(before),b=fn(after),vars=name==='ouvrirDemandesAdhesion'?['orga','def','grades','demandes']:['orga','tous','membresActuels','dejaInvites','eligibles'];for(const id of vars){const get=n=>n.body.body.find(x=>x.type==='VariableDeclaration'&&x.declarations[0].id.name===id);assert.deepEqual(strip(get(a)),strip(get(b)),name+'/'+id);}assert.deepEqual(strip(a.body.body[1]),strip(b.body.body[1]));for(const tree of [before,after])tree.body=tree.body.filter(n=>n!==fn(tree));}assert.deepEqual(strip(after),strip(before));assert.equal(execFileSync('git',['diff','--name-only',base,...(proof?[proof.codeCommit]:[]),'--','api','migrations','supabase','supabase.js','auth.js','data.js','forum.js','plateau-core.js','plateau-politique.js','style.css','i18n/plateau-init.js','i18n/sovarka-partis-resources.js','i18n/sovarka-droits-resources.js'],{cwd:root,encoding:'utf8'}),'');});
test('adhésions : six français exacts, neuf langues et quatre traductions existantes réutilisées',()=>{const c={};c.window=c;vm.createContext(c);for(const f of ['i18n/resources.js','i18n/sovarka-droits-resources.js','i18n/sovarka-partis-resources.js','i18n/organization-admissions-resources.js'])vm.runInContext(read(f),c);const m=JSON.parse(read('outils/audits/I18N-ADHESIONS-ORGANISATIONS-871-sources.json'));assert.equal(m.rows.length,6);assert.deepEqual(JSON.parse(JSON.stringify(c.RP_I18N_RESOURCES.fr.translation.organizationAdmissions)),Object.fromEntries(m.rows));for(const [lang,r]of Object.entries(c.RP_I18N_RESOURCES)){for(const [key,fr]of m.rows){assert.ok(r.translation.organizationAdmissions[key]?.trim());if(lang!=='fr')assert.notEqual(r.translation.organizationAdmissions[key],fr);}for(const k of m.reusedKeys){const [ns,key]=k.split('.');assert.ok(r.translation[ns][key]);}}assert.ok(read('plateau.html').indexOf('organization-admissions-resources.js')<read('plateau.html').indexOf('i18n/plateau-init.js'));});
